$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'ESAdapterEvidenceBridge.psm1') -Force; $c=[Collections.Generic.List[object]]::new(); function C($n,$b){[void]$c.Add([pscustomobject]@{case=$n;status=$(if($b){'passed'}else{'failed'})})}; $e=New-ESAdapterEvidenceSet -TaskId 'task-1' -AdapterId 'es-adapter.langgraph.v1' -AdapterVersion '0.1.0' -Observation @{eventCount=3;state='interrupted'}; $r=New-ESAdapterReceipt -Evidence $e -Decision review -IdempotencyKey 'same'; C 'evidence-valid' ((Test-ESAdapterEvidence -Evidence $e).status -eq 'passed'); C 'receipt-binding' ($r.evidenceSetHash -eq $e.evidenceSetHash); $platform=ConvertTo-ESPlatformEvidenceInput -AdapterEvidence $e -TaskId 'task-1' -SourceScopeHash ('a'*64) -ClaimId 'adapter-observation'; Import-Module (Join-Path $PSScriptRoot '..\Contracts\ESJsonSchemaLite.psm1') -Force; $schemaErrors=@(Test-ESJsonSchemaValue -SchemaPath (Join-Path $PSScriptRoot '..\Contracts\es-platform-evidence-v1.schema.json') -DefinitionName 'normalizedEvidenceSet' -Value $platform); C 'platform-contract-conversion' ($schemaErrors.Count -eq 0); $bad=$e|ConvertTo-Json -Depth 30|ConvertFrom-Json; $bad.items[0].outcome='failed'; try{Test-ESAdapterEvidence -Evidence $bad;C 'tamper-rejected' $false}catch{C 'tamper-rejected' $true}; try{New-ESAdapterReceipt -Evidence $e -Decision nope;C 'invalid-decision' $false}catch{C 'invalid-decision' $true}; $f=@($c|? status -eq 'failed'); [pscustomobject]@{schemaVersion=1;validator='Test-ESAdapterEvidenceBridge';status=$(if($f.Count){'failed'}else{'passed'});caseCount=$c.Count;passedCount=@($c|? status -eq 'passed').Count;failedCount=$f.Count;cases=@($c);runtimeStatus='runtime-not-run';claimsNotProven=@('TaskContextRuntime persistence','External framework runtime','Unity/host runtime')}|ConvertTo-Json -Depth 10;if($f.Count){exit 1}
